function renderBarChart(elId, data, opts) {
  const el = document.getElementById(elId);
  const max = opts.max !== undefined ? opts.max : Math.max(...data.map(d => d.value)) * 1.15;
  const min = opts.min !== undefined ? opts.min : 0;
  const range = max - min;
  data.forEach(d => {
    const row = document.createElement('div');
    row.className = 'bar-row';
    const pct = Math.max(((d.value - min) / range) * 100, 2);
    row.innerHTML = `
      <div class="bar-label">${d.label}</div>
      <div class="bar-track">
        <div class="bar-fill" style="width:${pct}%; background:${d.color};"></div>
      </div>
      <div class="bar-value">${d.display}</div>
    `;
    el.appendChild(row);
  });
}

